<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';
import type {BrowseContext} from '../types/model-browse';
import {trainingReaderApi,type TrainingTask,type TaskPage} from '../api/training-reader';
import {shownValue} from '../api/model-browse';
import {useReadScope} from '../composables/useReadScope';
import PageHeader from '../components/PageHeader.vue';
import ReadOnlyFacts from '../components/ReadOnlyFacts.vue';
const props=defineProps<{context:BrowseContext}>(),api=trainingReaderApi(props.context),reads=useReadScope(props.context);
const filters=reactive({query:'',status:'',kind:'',...props.context.memory.tasks?.filters}),cursors=ref<string[]>(props.context.memory.tasks?.cursors||['']),index=ref(props.context.memory.tasks?.index||0),page=ref<TaskPage|null>(null),task=ref<TrainingTask|null>(null),drawer=ref(false);
function close(){reads.cancel('detail');drawer.value=false;task.value=null}
function load(){close();props.context.memory.tasks={filters:{...filters},cursors:[...cursors.value],index:index.value};return reads.run('tasks',signal=>api.tasks({...filters,cursor:cursors.value[index.value]||''},signal),value=>{page.value=value})}
function search(){cursors.value=[''];index.value=0;void load()}
function next(){if(!page.value?.next_cursor)return;cursors.value=cursors.value.slice(0,index.value+1);cursors.value.push(page.value.next_cursor);index.value++;void load()}
function previous(){if(index.value){index.value--;void load()}}
function detail(row:TrainingTask){close();drawer.value=true;void reads.run('detail',signal=>api.task(row.task_id,signal),value=>{task.value=value})}
function report(row:TrainingTask){if(row.report_job_id)props.context.openReport?.({jobId:row.report_job_id,returnPage:'tasks'})}
onMounted(()=>void load());
</script>
<template><section class="catalog-preview" aria-label="训练任务只读中心"><PageHeader title="训练任务中心" eyebrow="训练管理 / 统一任务" description="读取原 Task Runtime 记录，执行与资源操作保留在原管理页。" badge="只读" @back="context.returnToManagement"/>
<form class="browse-filters" @submit.prevent="search"><el-input v-model="filters.query" aria-label="搜索任务ID或阶段" placeholder="任务 ID 或阶段"/><el-select v-for="[key,label] in [['status','持久状态'],['kind','任务类型']]" :key="key" v-model="filters[key as 'status'|'kind']" :aria-label="label" :placeholder="label"><el-option value="" :label="'全部'+label"/><el-option v-for="value in page?.filter_options[key]||[]" :key="value" :label="value" :value="value"/></el-select><div class="preview-actions"><el-button native-type="submit" type="primary" :disabled="reads.busy.tasks">查询任务</el-button><el-button :disabled="reads.busy.tasks" @click="load">刷新任务</el-button></div></form>
<el-alert v-if="reads.errors.tasks" :title="reads.errors.tasks" type="error" :closable="false"/><p v-if="reads.errors.tasks&&page" class="evidence-note">下方为上次读取快照，不能作为最新状态。</p>
<section class="browse-panel"><el-skeleton v-if="!page&&reads.busy.tasks" :rows="8" animated/><el-table v-else-if="page" :data="page.items" max-height="620" row-key="task_id" empty-text="当前条件下没有训练任务"><el-table-column label="任务 / 关联" min-width="190"><template #default="{row}"><strong>{{ row.task_id }}</strong><small class="browse-secondary">{{ row.kind }}</small><small class="browse-secondary">算法 {{ row.algorithm_name||row.algorithm_id||'未提供' }} · 版本 {{ row.version_id||'未提供' }}</small></template></el-table-column><el-table-column label="状态 / 进度" min-width="150"><template #default="{row}"><el-tag type="info" effect="plain">{{ row.status }}</el-tag><small class="browse-secondary">{{ row.phase||'阶段未提供' }} · {{ shownValue(row.progress_percent) }}%</small><small class="browse-secondary">{{ row.resource_wait_reason||row.error }}</small></template></el-table-column><el-table-column label="时间 / 执行" min-width="175"><template #default="{row}"><small>{{ row.created_at||'创建时间未提供' }}</small><small class="browse-secondary">结束 {{ row.finished_at||'未提供' }}</small><small class="browse-secondary">{{ row.worker_id||'Worker 未分配或未记录' }} · {{ row.resource_key||'资源未提供' }}</small></template></el-table-column><el-table-column label="操作" width="105"><template #default="{row}"><el-button link type="primary" :aria-label="`查看任务${row.task_id}`" @click="detail(row)">详情</el-button><el-button v-if="row.report_job_id&&context.openReport" link @click="report(row)">报告</el-button></template></el-table-column></el-table><footer v-if="page" class="preview-pagination"><span>第 {{ index+1 }} 页 · 本页 {{ page.items.length }} 条</span><div class="preview-actions"><el-button :disabled="!index||reads.busy.tasks" @click="previous">上一页</el-button><el-button :disabled="!page.next_cursor||reads.busy.tasks" @click="next">下一页</el-button></div></footer></section>
<el-drawer :model-value="drawer" title="训练任务详情" size="min(680px,100vw)" :append-to-body="false" :lock-scroll="false" :before-close="close"><el-skeleton v-if="reads.busy.detail" :rows="8" animated/><el-alert v-else-if="reads.errors.detail" :title="reads.errors.detail" type="error" :closable="false"/><div v-else-if="task" class="evidence-details"><h3>身份与状态</h3><ReadOnlyFacts :fields="[['Task ID',task.task_id],['类型',task.kind],['状态',task.status],['持久状态',task.persisted_status],['算法',task.algorithm_id],['版本',task.version_id],['进度（%）',task.progress_percent],['阶段',task.phase],['元数据读取状态',task.metadata_state]]"/><h3>执行证据</h3><ReadOnlyFacts :fields="[['创建',task.created_at],['开始',task.started_at],['结束',task.finished_at],['Worker',task.worker_id],['资源键',task.resource_key],['等待原因',task.resource_wait_reason]]"/><ReadOnlyFacts :fields="Object.entries(task.execution||{})"/><h3>训练配置摘要</h3><ReadOnlyFacts :fields="Object.entries(task.configuration||{})"/><h4>请求执行配置（不等于实际分配）</h4><ReadOnlyFacts :fields="Object.entries(task.requested_execution||{})"/><h3>诊断</h3><ReadOnlyFacts :fields="[['失败原因',task.error]]"/></div><template #footer><el-button @click="close">返回任务列表</el-button><el-button v-if="task?.report_job_id&&context.openReport" @click="report(task)">阅读训练报告</el-button></template></el-drawer></section></template>
